/**
 * Radix logotipi — Brendbuk 1.1 (02–03).
 *
 * Yagona manba: SVG yo'llari shu faylda, boshqa hech qayerda qayta
 * chizilmaydi. Brendbuk taqiqlari shu komponentga kiritilgan:
 *
 *   · Belgi doim chapda, yozuv doim kichik harflarda va doim belgi bilan.
 *     Yozuv yolg'iz ishlatilmaydi — shuning uchun `wordmark` degan
 *     alohida eksport yo'q.
 *   · To'liq logotip ekranda 96 px dan kichik bo'lmaydi. Kichikroq joyda
 *     faqat belgi qoladi — buni chaqiruvchi eslab yurmaydi, `Logo`
 *     o'zi hal qiladi (`height` bo'yicha).
 *   · Ranglar o'zgartirilmaydi: och fonda A variant (Ildiz kvadrat, Tosh
 *     yozuv), to'q fonda B variant (Nihol kvadrat, oq yozuv).
 *   · Cho'zish, burish, soya va effekt yo'q — o'lcham faqat balandlik
 *     orqali, nisbat saqlanadi.
 */

/** Xavfsiz maydon: x — o'rik nuqta diametri (64 lik to'rda 14), kerak 2x. */
const SAFE_AREA_RATIO = 28 / 64

/** 96 px kenglikdagi to'liq logotip shuncha balandlikka to'g'ri keladi. */
const MIN_FULL_HEIGHT = Math.ceil((96 * 64) / 185)

type Variant = 'light' | 'dark'

/** A varianti och fon uchun, B varianti to'q fon uchun (brendbuk 02). */
const PALETTE: Record<Variant, { plate: string; word: string }> = {
  light: { plate: '#12352F', word: '#1B2421' },
  dark: { plate: '#2E9E6B', word: '#FFFFFF' },
}

