interface MarkProps {
  /** Belgi tomoni, px. */
  size?: number
  variant?: Variant
  className?: string
}

/**
 * Belgi yolg'iz — ilova ikonkasi, favicon, avatar, muhr (brendbuk 02).
 * Yozuvsiz ishlatish RUXSAT ETILGAN yagona holat shu.
 */
export function RadixMark({ size = 36, variant = 'light', className }: MarkProps) {
  const { plate } = PALETTE[variant]
  return (
    <svg
      viewBox="0 0 64 64"
      width={size}
      height={size}
      role="img"
      aria-label="Radix"
      className={className}
      style={{ display: 'block' }}
    >
      <rect width="64" height="64" rx="17" fill={plate} />
      <path
        d="M12 36 L19 32.5 L27.5 47.5 L39 15.5 H47"
        fill="none"
        stroke="#FFFFFF"
        strokeWidth="8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx="50" cy="15.5" r="7" fill="#F29B55" />
    </svg>
  )
}

interface LogoProps {
  /** Logotip balandligi, px. Kenglik nisbatdan chiqadi — cho'zilmaydi. */
  height?: number
  variant?: Variant
  /** Har ikki yonga 2x bo'sh joy qo'shadi (brendbuk 03). */
  safeArea?: boolean
  className?: string
}

/**
 * To'liq logotip — belgi va yozuv birga.
 *
 * Balandlik 96 px kenglikka yetmasa, yozuv tushib qoladi va faqat belgi
 * chiziladi: brendbuk kichik o'lchamda aynan shuni talab qiladi.
 */
export function Logo({ height = 32, variant = 'light', safeArea, className }: LogoProps) {
  const { plate, word } = PALETTE[variant]

  if (height < MIN_FULL_HEIGHT) {
    return <RadixMark size={height} variant={variant} className={className} />
  }

  const pad = safeArea ? height * SAFE_AREA_RATIO : 0
  return (
    <svg
      viewBox={`${-pad} ${-pad} ${185 + pad * 2} ${64 + pad * 2}`}
      height={height + pad * 2}
      width={((185 + pad * 2) * height) / 64}
      role="img"
      aria-label="Radix"
      className={className}
      style={{ display: 'block' }}
    >
      <rect width="64" height="64" rx="17" fill={plate} />
      <path
        d="M12 36 L19 32.5 L27.5 47.5 L39 15.5 H47"
        fill="none"
        stroke="#FFFFFF"
        strokeWidth="8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx="50" cy="15.5" r="7" fill="#F29B55" />
      <path d={WORDMARK_PATH} fill={word} />
    </svg>
  )
}
